<?php
declare(strict_types=1);
namespace Hostider\OfflineBackup;
use Hostider\Core\Config;
use Hostider\Core\Database\{Database,Migrator};
final class Workspace
{
 private ?NativeSchema $model=null;
 private function __construct(public readonly string $id,public readonly string $root,#[\SensitiveParameter] private array $config,public readonly Database $admin,private array $state){}
 public static function base():string{$p=dirname(__DIR__,2).'/storage/offline-rehearsal';if(!file_exists($p)){Guard::require(mkdir($p,0700,true),'BASE');}Guard::directory($p);return $p;}
 public static function create(#[\SensitiveParameter] array $config):self{$admin=Guard::config($config);Guard::databaseSpace($admin);$id=bin2hex(random_bytes(12));$p=self::base().'/'.$id;Guard::mkdir($p);$state=['id'=>$id,'token'=>bin2hex(random_bytes(32)),'source'=>'f6f_src_'.$id,'source_state'=>'INITIALIZING','backup'=>'NONE','target'=>null,'target_state'=>'NONE','reference'=>null,'restore_nonce'=>null];$w=new self($id,$p,$config,$admin,$state);$w->persist();Guard::mkdir($p.'/source');Guard::mkdir($p.'/source/attachments');Guard::mkdir($p.'/source/documents');$db=$w->make('source');(new Migrator($db,dirname(__DIR__,2).'/migrations'))->migrate();$w->model=NativeSchema::capture($db);$w->state['source_state']='READY';$w->persist();return $w;}
 public static function load(string $id,#[\SensitiveParameter] array $config):self{$admin=Guard::config($config);Guard::id($id);$p=self::base().'/'.$id;Guard::directory($p);Guard::file($p.'/state.json');$s=json_decode(file_get_contents($p.'/state.json'),true,16,JSON_THROW_ON_ERROR);Guard::fields($s,['id','token','source','source_state','backup','target','target_state','reference','restore_nonce']);Guard::require($s['id']===$id&&preg_match('/\A[a-f0-9]{64}\z/D',$s['token'])===1&&$s['source']==='f6f_src_'.$id,'BINDING');return new self($id,$p,$config,$admin,$s);}
 private function persist():void{Guard::save($this->root.'/state.json',$this->state);}
 public function state():array{return $this->state;}
 public function set(string $field,mixed $value):void{Guard::require(in_array($field,['source_state','backup','target_state'],true),'STATE_FIELD');$edges=match($field){'source_state'=>['INITIALIZING'=>['READY'],'READY'=>['SEALED'],'SEALED'=>[]],'backup'=>['NONE'=>['WRITING'],'WRITING'=>['FAILED','COMPLETE'],'FAILED'=>['NONE'],'COMPLETE'=>[]],'target_state'=>['NONE'=>['RESTORING','FAILED'],'RESTORING'=>['FAILED','COMPLETE'],'FAILED'=>['NONE'],'COMPLETE'=>[]],default=>throw new \RuntimeException('F6F_STATE_FIELD')};Guard::require($value===$this->state[$field]||in_array($value,$edges[$this->state[$field]]??[],true),'STATE_TRANSITION');$this->state[$field]=$value;$this->persist();}
 public function appConfig():Config{return new Config('test','https://offline.example.invalid',$this->config['app_key'],'mysql:host=127.0.0.1;port='.$this->config['port'].';dbname='.$this->state['source'].';charset=utf8mb4',$this->config['account'],$this->config['password']);}
 public function applicationKey():string{return base64_decode($this->config['app_key'],true);}
 public function binding():string{return Guard::hash([$this->id,hash('sha256',$this->state['token']),'NATIVE_SYNTHETIC_ONLY']);}
 private function schema(string $kind):string{$s=$this->state[$kind]??null;Guard::require(is_string($s)&&preg_match('/\Af6f_'.match($kind){'source'=>'src','target'=>'dst','reference'=>'ref',default=>throw new \RuntimeException('F6F_KIND')}.'_[a-f0-9]{24}\z/D',$s)===1,'SCHEMA_BINDING');return $s;}
 public function db(string $kind='source'):Database{$db=Guard::connect($this->config,$this->schema($kind));$v=$db->execute('SELECT operation_id,kind,token_hash FROM f6f_control WHERE id=1')->fetch();Guard::require($v&&$v['operation_id']===$this->id&&$v['kind']===$kind&&hash_equals($v['token_hash'],hash('sha256',$this->state['token'])),'OWNERSHIP');return $db;}
 private function make(string $kind):Database{Guard::require(in_array($kind,['source','target','reference'],true),'KIND');if($kind!=='source'){$this->state[$kind]='f6f_'.($kind==='target'?'dst':'ref').'_'.bin2hex(random_bytes(12));$this->persist();}$schema=$this->schema($kind);$this->admin->execute('CREATE DATABASE '.Guard::name($schema).' CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci');$db=Guard::connect($this->config,$schema);$db->execute('CREATE TABLE f6f_control(id INT PRIMARY KEY CHECK(id=1),operation_id CHAR(24) NOT NULL,kind VARCHAR(16) NOT NULL,token_hash CHAR(64) NOT NULL) ENGINE=InnoDB');$db->execute('INSERT INTO f6f_control VALUES(1,?,?,?)',[$this->id,$kind,hash('sha256',$this->state['token'])]);return $db;}
 public function model():NativeSchema{if($this->model!==null){return $this->model;}Guard::require($this->state['reference']===null,'REFERENCE_PENDING');$db=$this->make('reference');try{(new Migrator($db,dirname(__DIR__,2).'/migrations'))->migrate();return $this->model=NativeSchema::capture($db);}finally{$this->drop('reference');}}
 public function newTarget():Database{Guard::require($this->state['target']===null&&$this->state['target_state']==='NONE','NO_TARGET_REPLAY');$db=$this->make('target');$this->set('target_state','RESTORING');(new Migrator($db,dirname(__DIR__,2).'/migrations'))->migrate();return $db;}
 public function drop(string $kind):void{Guard::require(in_array($kind,['target','reference'],true)&&($kind!=='target'||$this->state['target_state']!=='COMPLETE'),'NO_SOURCE_OR_COMPLETE_DELETE');$this->db($kind);$schema=$this->schema($kind);$this->admin->execute('DROP DATABASE '.Guard::name($schema));$this->state[$kind]=null;if($kind==='target'){$this->state['target_state']='NONE';}$this->persist();}
 public function fence():void{Guard::config($this->config);$this->db();}
 public function lock():mixed{$this->fence();Guard::directory($this->root);$p=$this->root.'/operation.lock';if(!file_exists($p)){$f=Guard::open($p,'x+b');}else{$f=Guard::open($p,'r+b');}Guard::require(flock($f,LOCK_EX|LOCK_NB),'BUSY');Guard::file($this->root.'/state.json');$latest=json_decode(file_get_contents($this->root.'/state.json'),true,16,JSON_THROW_ON_ERROR);Guard::require($latest['id']===$this->id&&$latest['token']===$this->state['token']&&$latest['source']===$this->state['source'],'STATE_IDENTITY');$this->state=$latest;return $f;}
 public function fileRoot(string $group,bool $target=false):string{Guard::require(in_array($group,['attachments','documents'],true),'FILE_GROUP');return $this->root.'/'.($target?'restored':'source').'/'.$group;}
 public function seal():array{$lock=$this->lock();$db=$this->db();try{Guard::require($this->state['source_state']==='READY','SEAL_STATE');$m=$this->model();$m->assertSchema($db);$m->lock($db);try{$image=$m->snapshot($db);$catalog=ManagedFiles::catalog(ManagedFiles::decoded($image));$spec=ManagedFiles::inspect($this,$catalog,false,false);foreach(['attachments','documents'] as $g){foreach(new \DirectoryIterator($this->fileRoot($g)) as $p){if($p->isDot()){continue;}if($g==='attachments'&&$p->getFilename()==='.lock'){ManagedFiles::auxiliary($p->getPathname(),false);}else{Guard::file($p->getPathname());}Guard::require(chmod($p->getPathname(),0400),'FREEZE_FILE');}Guard::require(chmod($this->fileRoot($g),0500),'FREEZE_DIRECTORY');Guard::syncDir($this->fileRoot($g),0500);}Guard::require(chmod($this->root.'/source',0500),'FREEZE_ROOT');Guard::syncDir($this->root.'/source',0500);Guard::save($this->root.'/seal.json',['binding'=>$this->binding(),'files'=>$spec]);$this->set('source_state','SEALED');return ['status'=>'SYNTHETIC_SOURCE_QUIESCED','files'=>count($spec),'production_maintenance'=>false];}finally{$db->execute('UNLOCK TABLES');}}finally{fclose($lock);}}
 public function frozen():array{Guard::require($this->state['source_state']==='SEALED','QUIESCENCE_REQUIRED');Guard::directory($this->root.'/source',0500);foreach(['attachments','documents'] as $g){Guard::directory($this->fileRoot($g),0500);}Guard::file($this->root.'/seal.json');$v=json_decode(file_get_contents($this->root.'/seal.json'),true,16,JSON_THROW_ON_ERROR);Guard::require($v['binding']===$this->binding(),'SEAL_BINDING');return $v['files'];}
 public function restoredDirectory():void{Guard::require($this->state['target']!==null&&$this->state['restore_nonce']===null&&!file_exists($this->root.'/restored')&&!is_link($this->root.'/restored'),'NO_RESTORE_OVERWRITE');$this->state['restore_nonce']=bin2hex(random_bytes(32));$this->persist();Guard::mkdir($this->root.'/restored');Guard::save($this->root.'/restored/.owned.json',['binding'=>$this->binding(),'owner'=>hash('sha256',$this->state['restore_nonce'])]);foreach(['attachments','documents'] as $g){Guard::mkdir($this->fileRoot($g,true));}}
 private function removeRestored():void{if(!file_exists($this->root.'/restored')&&!is_link($this->root.'/restored')){return;}Guard::require(is_string($this->state['restore_nonce']),'UNOWNED_RESTORE_PATH');Guard::directory($this->root.'/restored');Guard::file($this->root.'/restored/.owned.json');$m=json_decode(file_get_contents($this->root.'/restored/.owned.json'),true,8,JSON_THROW_ON_ERROR);Guard::require($m===['binding'=>$this->binding(),'owner'=>hash('sha256',$this->state['restore_nonce'])],'RESTORE_PATH_OWNERSHIP');self::removeTree($this->root.'/restored');$this->state['restore_nonce']=null;$this->persist();}
 public function abortTarget():void{if($this->state['target']!==null){$this->drop('target');}$this->removeRestored();$this->set('target_state','FAILED');}
 public function cleanup():array{$l=$this->lock();try{Guard::require($this->state['target_state']!=='COMPLETE','COMPLETED_TARGET_PRESERVED');$p=$this->root.'/backup.partial';if(file_exists($p)||is_link($p)){Guard::require(in_array($this->state['backup'],['WRITING','FAILED'],true),'UNOWNED_PARTIAL');Guard::file($p);Guard::require(unlink($p),'PARTIAL_CLEAN');}if($this->state['reference']!==null){$this->drop('reference');}if($this->state['target']!==null){$this->drop('target');}$this->removeRestored();$this->set('target_state','NONE');if($this->state['backup']!=='COMPLETE'){if($this->state['backup']==='WRITING'){$this->set('backup','FAILED');}$this->set('backup','NONE');}return ['status'=>'OWNED_INCOMPLETE_STATE_CLEANED','source_preserved'=>true];}finally{fclose($l);}}
 private static function removeTree(string $p):void{Guard::directory($p);$items=[];foreach(new \DirectoryIterator($p) as $e){if(!$e->isDot()){$items[]=$e->getPathname();}}Guard::require(count($items)<=Guard::MAX_FILES+8,'CLEAN_BOUND');foreach($items as $q){if(is_dir($q)&&!is_link($q)){self::removeTree($q);}else{Guard::file($q);Guard::require(unlink($q),'CLEAN_FILE');}}Guard::require(rmdir($p),'CLEAN_DIRECTORY');}
}
